import{_ as t,o,c as a,a3 as d}from"./chunks/framework.I6s8z2kk.js";const p=JSON.parse('{"title":"Purchases and payments","description":"","frontmatter":{},"headers":[],"relativePath":"dev/domain/purchase.md","filePath":"dev/domain/purchase.md"}'),n={name:"dev/domain/purchase.md"};function c(r,e,s,i,h,l){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="purchases-and-payments" tabindex="-1">Purchases and payments <a class="header-anchor" href="#purchases-and-payments" aria-label="Permalink to &quot;Purchases and payments&quot;">​</a></h1><p>The <strong>Purchase</strong> module records what a client buys and how it is paid. It also computes the platform fee.</p><h2 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to &quot;Concepts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Purchase</strong></td><td>One checkout. Status <code>pending</code>, <code>confirmed</code>, <code>cancelled</code>, <code>completed</code>. Has items. Gets a unique 6-character <code>code</code> on insert (<code>HasUniqueCode</code>, same format as the <a href="./reservations#reservation-code">reservation code</a>).</td></tr><tr><td><strong>Purchase item</strong></td><td><code>total = unit_price × quantity − discount + tax</code>. Its <code>purchasable</code> (morph alias) is a <code>reservation</code>, <code>client_package</code>, <code>client_membership</code>, <code>stay_invoice</code> (an extra charge on a stabling stay, see <a href="./reservations#rules-per-type">Reservations</a>) or <code>subscription</code>.</td></tr><tr><td><strong>Payment</strong></td><td>One <strong>attempt</strong>. Status <code>pending</code>, <code>processing</code>, <code>succeeded</code>, <code>failed</code>, <code>cancelled</code>, <code>expired</code>, <code>refunded</code>.</td></tr><tr><td><strong>Adjustment</strong></td><td>A promotion or coupon discount applied to a purchase. See <a href="./promotions">Promotions</a>.</td></tr><tr><td><strong>PurchaseFee</strong></td><td>The platform fee snapshot for a center-merchant purchase.</td></tr></tbody></table><p>Purchase <code>source</code> is <code>client</code>, <code>center</code> or <code>system</code>. <code>channel</code> is <code>khyyal_app</code>, <code>center_app</code>, <code>khyyal_web</code>, <code>center_web</code> or <code>center_dashboard</code>. Payment methods are <code>online</code>, <code>cash_on_arrival</code> and <code>manual</code>.</p><h2 id="state-changes" tabindex="-1">State changes <a class="header-anchor" href="#state-changes" aria-label="Permalink to &quot;State changes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Entity</th><th>Allowed transitions</th><th>Only through</th></tr></thead><tbody><tr><td>Purchase</td><td><code>pending → confirmed</code>, <code>pending|confirmed → cancelled</code>, <code>confirmed → completed</code></td><td><code>PurchaseStateService</code></td></tr><tr><td>Payment</td><td><code>pending → processing</code>, <code>pending|processing → succeeded|failed|cancelled|expired</code></td><td><code>PaymentStateService</code></td></tr></tbody></table><ul><li>Same-status transitions are a no-op.</li><li><code>succeeded</code> is final except for refunds through <code>recordRefund</code>: cumulative, amount ≤ remaining, and status <code>refunded</code> only when fully refunded.</li><li>Gateways return a <code>PaymentStatus</code> and never write <code>Payment.status</code>.</li></ul><h2 id="refunding-a-purchase-from-the-center" tabindex="-1">Refunding a purchase from the center <a class="header-anchor" href="#refunding-a-purchase-from-the-center" aria-label="Permalink to &quot;Refunding a purchase from the center&quot;">​</a></h2><p><code>POST centers/{center}/purchases/{purchase}/refund</code> (also under <code>admin/centers/{center}</code>; idempotent; <code>reservations.edit</code> for center users, <code>centers.manage_reservations</code> for system users; the purchase must pass <code>CenterPurchaseQuery::visible()</code>, otherwise 404) runs <code>Modules\\Reservations\\Actions\\RefundPurchase</code> in one transaction:</p><ol><li>The purchase must be <code>confirmed</code> (<code>purchase_not_refundable</code>) and have a <code>succeeded</code> payment with something left to refund (<code>nothing_to_refund</code>).</li><li>The purchase is cancelled through <code>PurchaseStateService</code>, then everything it sold is cancelled (see <a href="./reservations#packages-and-memberships">Reservations</a>).</li><li>Each payment&#39;s whole remaining amount is refunded last: online payments through their gateway (a refusal or exception gives <code>purchase_refund_failed</code> and rolls everything back), manual payments without a gateway call. <code>recordRefund</code> then marks them <code>refunded</code>.</li></ol><p>There is no partial refund on this endpoint. Fee reversal, redemption release, ledger sync and buyer notifications come from the existing <code>PurchaseCancelled</code> and <code>PaymentRefunded</code> listeners. Errors use <code>ReservationNotAllowedException</code> (422 with <code>reason</code>).</p><h2 id="payments-are-append-only-attempts" tabindex="-1">Payments are append-only attempts <a class="header-anchor" href="#payments-are-append-only-attempts" aria-label="Permalink to &quot;Payments are append-only attempts&quot;">​</a></h2><p>A retry is a <strong>new</strong> Payment row. Never revive failed or expired payments, and never delete abandoned pending ones. A purchase is confirmed only when its succeeded payments sum to at least <code>total_amount</code>.</p><p>Item and payment amounts must be &gt; 0. Manual payment is allowed only when the source is <code>center</code>.</p><h2 id="pricing-order" tabindex="-1">Pricing order <a class="header-anchor" href="#pricing-order" aria-label="Permalink to &quot;Pricing order&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>line subtotals → promotions / coupon → total = subtotal − discount + tax → platform fee</span></span></code></pre></div><p>The <strong>fee is what the center owes the platform</strong>. It never changes what the client pays.</p><ul><li>Fee base = <code>total_amount + sum(adjustment.amount − center_share_amount)</code>.</li><li>Fee = <code>intdiv(base × bps, 10000) + fixed</code>, raised to the minimum, cut to the maximum, capped at the base. A base ≤ 0 means a fee of 0.</li><li>Rule resolution picks the first <strong>active</strong> <code>FeeRule</code> in this order: center+channel, platform+channel, center fallback, platform fallback. There is one rule per <code>(center, channel)</code>.</li><li>Write exactly <strong>one <code>PurchaseFee</code> per center-merchant purchase</strong>, even when it is 0. Reverse it (<code>reversed_at</code>) on cancel or full refund; partial refunds keep it. Never recompute or delete fee rows.</li><li>Only system users with <code>fees.manage</code> manage fee rules (<code>admin/fee-rules</code>).</li></ul><h2 id="channel-resolution" tabindex="-1">Channel resolution <a class="header-anchor" href="#channel-resolution" aria-label="Permalink to &quot;Channel resolution&quot;">​</a></h2><p>Client requests take the channel from the <code>X-Channel</code> header and may not send <code>center_dashboard</code>. The center dashboard uses <code>center_dashboard</code>. System users get <code>null</code>. <code>center_app</code> and <code>center_web</code> fall back to <code>null</code> unless the center has <code>custom_site_enabled</code>.</p><h2 id="gateways-and-webhooks" tabindex="-1">Gateways and webhooks <a class="header-anchor" href="#gateways-and-webhooks" aria-label="Permalink to &quot;Gateways and webhooks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Rule</th><th>Detail</th></tr></thead><tbody><tr><td>Never trust the browser</td><td>Do not mark a payment succeeded from a callback. Call <code>verify()</code> (<code>POST clients/payments/{payment}/verify</code>, <code>POST centers/{center}/payments/{payment}/verify</code>), which syncs server-side and checks the amount.</td></tr><tr><td>Units</td><td><strong>Tamara takes major units</strong> (divide by 100); <strong>Moyasar takes halalas</strong>.</td></tr><tr><td>Reference</td><td>Use the Payment id as the provider reference.</td></tr><tr><td>Secrets</td><td>No card data reaches the backend; redact secrets in logs; retry only <code>initialize</code>.</td></tr><tr><td>Boundary</td><td>Gateway code must not reference Reservation or Subscription.</td></tr><tr><td>Webhooks</td><td>Deduplicate on <code>(gateway, external_event_id)</code>, recording the attempt in its own transaction first. Already processed is a no-op; on failure set <code>failed_at</code> and rethrow. Handlers only map an event to <code>{payment_order_id, status}</code>; pending results do nothing.</td></tr></tbody></table><h3 id="provider-status-mappings" tabindex="-1">Provider status mappings <a class="header-anchor" href="#provider-status-mappings" aria-label="Permalink to &quot;Provider status mappings&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Provider</th><th>Mapping</th></tr></thead><tbody><tr><td>Moyasar</td><td>The failure event is spelled <code>payment_faild</code> <strong>on purpose</strong> (do not fix it). <code>authorized</code> means Processing. <code>refunded</code> and <code>verified</code> events change nothing.</td></tr><tr><td>Tamara</td><td><code>authorised</code>/<code>captured</code> = Succeeded; <code>approved</code>/<code>new</code> = Processing; <code>declined</code> = Failed; <code>canceled</code>/<code>cancelled</code> = Cancelled; <code>expired</code> = Expired. Refund events change nothing.</td></tr></tbody></table><h2 id="admin-and-center-views" tabindex="-1">Admin and center views <a class="header-anchor" href="#admin-and-center-views" aria-label="Permalink to &quot;Admin and center views&quot;">​</a></h2><p><code>admin/purchases</code> and <code>centers/{center}/purchases</code> list and show purchases and export them. Every purchase resource includes <code>code</code>. <code>centers/{center}/purchases/code/{code}</code> (also under <code>admin/centers/{center}/…</code>) shows a purchase by its code with the same visibility rules as showing it by ID; clients list their own with <code>clients/purchases</code> (newest first, optional <code>status</code>) and look one up with <code>clients/purchases/{purchase}</code> or <code>clients/purchases/code/{code}</code>. Admins also get <code>admin/purchases/{purchase}/financials</code>. Center users see purchases according to their <a href="./../conventions/permissions">permissions</a>.</p><p><code>admin/purchases</code> and its export take <code>sort</code> (<code>AdminPurchaseQuery::SORTS</code>): <code>created_at</code> or <code>total_amount</code>, <code>-</code> for descending; newest first without it. See <a href="./../conventions/coding#list-sorting">List sorting</a>.</p>',28)])])}const m=t(n,[["render",c]]);export{p as __pageData,m as default};
